
using System;
using System.Collections.Generic;

namespace StoreManagement.Api.Models;

public class Transaction
{
    public int Id { get; set; }

    // Generated by the originating device.
    // Must be unique to prevent duplicate transaction headers.
    public Guid TransactionId { get; set; }

    public int TransactionTypeId { get; set; }

    public int StoreId { get; set; }

    public string? UserId { get; set; }

    public int? DeviceId { get; set; }

    // Device transaction time, normalized to UTC.
    public DateTime TransactionDateUtc { get; set; }

    // Set by the server when the transaction is received.
    public DateTime ReceivedAtUtc { get; set; } = DateTime.UtcNow;

    // Receipt number, delivery note, SRS/GRS, promo ID, etc.
    public string? ReferenceNumber { get; set; }

    // Groups transaction lines or transactions in a physical count.
    public Guid? CountSessionId { get; set; }

    // Examples: POSTED, VOIDED, CANCELLED.
    public string Status { get; set; } = "POSTED";

    public string? Remarks { get; set; }

    public TransactionType? TransactionType { get; set; }

    public Store? Store { get; set; }

    public Device? Device { get; set; }

    public ICollection<TransactionLine> Lines { get; set; }
        = new List<TransactionLine>();
}
